from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_date, remaining_points)
        self._entries = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")

        # 1 point per whole currency unit (floor)
        points = int(amount)
        available_date = day + timedelta(days=14)
        self._entries.setdefault(customer, []).append([available_date, points])
        return points

    def balance(self, customer: str, day: date) -> int:
        entries = self._entries.get(customer, [])
        return sum(pts for avail, pts in entries if avail <= day and pts > 0)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points must be a positive multiple of 100")

        entries = self._entries.get(customer, [])

        # Sum of eligible (available) points
        eligible = [(i, e) for i, e in enumerate(entries)
                    if e[0] <= day and e[1] > 0]
        total_available = sum(e[1] for _, e in eligible)

        if points > total_available:
            raise ValueError("Insufficient available points")

        remaining = points
        # Spend oldest available entries first
        eligible.sort(key=lambda x: x[1][0])
        for idx, entry in eligible:
            if remaining == 0:
                break
            take = min(entry[1], remaining)
            entry[1] -= take
            remaining -= take
